const envelope = $input.first().json;
const raw = envelope.body ?? envelope;
const payload = raw.payload && typeof raw.payload === 'object' ? raw.payload : {};
const sensitivePattern = /(password|secret|token|authorization|api[_-]?key|cookie|credential)/i;
const sensitiveFields = [];
function scan(value, path = 'body') {
  if (!value || typeof value !== 'object') return;
  for (const [key, nested] of Object.entries(value)) {
    const nextPath = `${path}.${key}`;
    if (sensitivePattern.test(key)) sensitiveFields.push(nextPath);
    if (nested && typeof nested === 'object') scan(nested, nextPath);
  }
}
scan(raw);
const requestId = String(raw.requestId ?? `continuity-${Date.now()}`);
const unavailableProfessionalId = String(payload.unavailableProfessionalId ?? '');
const professionals = Array.isArray(payload.professionals) ? payload.professionals : [];
const sessions = Array.isArray(payload.sessions) ? payload.sessions : [];
const errors = [];
if (!unavailableProfessionalId) errors.push('unavailableProfessionalId is required');
if (!professionals.length) errors.push('professionals dataset is required');
if (!sessions.length) errors.push('sessions dataset is required');
if (sensitiveFields.length) errors.push('credential-like fields are forbidden');
let hash = 2166136261;
for (const char of `${requestId}:${unavailableProfessionalId}`) { hash ^= char.charCodeAt(0); hash = Math.imul(hash, 16777619); }
const idempotencyKey = `continuity-${(hash >>> 0).toString(16)}`;
return [{ json: {
  valid: errors.length === 0, errors, requestId, unavailableProfessionalId, professionals, sessions,
  simulateFailure: Boolean(payload.simulateFailure),
  correlationId: `af_continuity_${requestId}`.replace(/[^a-zA-Z0-9_-]/g, '_').slice(0, 100),
  idempotencyKey, receivedAt: new Date().toISOString(), mode: 'portfolio-sandbox'
} }];

const ctx = $input.first().json;
const now = Date.now();
const affectedSessions = ctx.sessions.filter((session) =>
  session.professionalId === ctx.unavailableProfessionalId &&
  session.status === 'scheduled' &&
  new Date(session.startsAt).getTime() > now
);
return [{ json: { ...ctx, affectedSessions, affectedCount: affectedSessions.length, hasAffectedSessions: affectedSessions.length > 0 } }];

const ctx = $input.first().json;
const unavailable = ctx.professionals.find((item) => item.id === ctx.unavailableProfessionalId);
const requiredSlots = [...new Set(ctx.affectedSessions.map((item) => item.slot))];
const requiredSkills = [...new Set(ctx.affectedSessions.map((item) => item.serviceType))];
const candidates = ctx.professionals
  .filter((item) => item.active && item.role === unavailable?.role && item.id !== ctx.unavailableProfessionalId)
  .map((candidate) => {
    const availability = Array.isArray(candidate.availability) ? candidate.availability : [];
    const skills = Array.isArray(candidate.skills) ? candidate.skills : [];
    const coveredSlots = requiredSlots.filter((slot) => availability.includes(slot));
    const coveredSkills = requiredSkills.filter((skill) => skills.includes(skill));
    const currentLoad = ctx.sessions.filter((session) => session.professionalId === candidate.id && session.status === 'scheduled').length;
    const availabilityRatio = requiredSlots.length ? coveredSlots.length / requiredSlots.length : 0;
    const skillRatio = requiredSkills.length ? coveredSkills.length / requiredSkills.length : 0;
    return {
      professionalId: candidate.id, name: candidate.name, priority: Number(candidate.priority ?? 0), currentLoad,
      availabilityRatio, skillRatio, fullCoverage: availabilityRatio === 1,
      reasons: [`${coveredSlots.length}/${requiredSlots.length} time windows`, `${coveredSkills.length}/${requiredSkills.length} service skills`, `${currentLoad} existing sessions`]
    };
  });
return [{ json: { ...ctx, requiredSlots, requiredSkills, candidates, hasCandidates: candidates.some((item) => item.fullCoverage) } }];

const ctx = $input.first().json;
const scorecard = ctx.candidates.map((candidate) => ({
  ...candidate,
  score: Math.max(0, Math.min(100, Math.round(candidate.priority * 0.45 + candidate.availabilityRatio * 35 + candidate.skillRatio * 20 - candidate.currentLoad * 3)))
})).sort((a, b) => b.score - a.score);
const complete = scorecard.filter((candidate) => candidate.fullCoverage);
const selected = complete[0];
const fallback = complete[1] ?? null;
const sessionUpdates = ctx.affectedSessions.map((session) => ({
  sessionId: session.id, memberAlias: session.memberAlias, fromProfessionalId: session.professionalId,
  toProfessionalId: selected.professionalId, expectedVersion: Number(session.version)
}));
return [{ json: { ...ctx, scorecard, selected, fallback, sessionUpdates } }];

const ctx = $input.first().json;
const selectedName = ctx.selected.name || ctx.selected.professionalId;
const explanation = `${selectedName} is recommended because the candidate covers every affected time window, matches ${Math.round(ctx.selected.skillRatio * 100)}% of the required service skills, and has an operational score of ${ctx.selected.score}/100. The proposal changes only future scheduled sessions and remains blocked until human approval.`;
return [{ json: { ...ctx, explanation } }];

const ctx = $input.first().json;
const proposal = {
  scenario: 'continuity', contractVersion: '2.0',
  outcome: `${ctx.affectedCount} future session${ctx.affectedCount === 1 ? '' : 's'} ready for safe reassignment`,
  explanation: ctx.explanation,
  businessRules: ['future sessions only', 'same-role replacement', 'complete time-window coverage', 'optimistic version check', 'human approval required'],
  proposedAction: {
    selectedCandidate: ctx.selected.professionalId,
    fallbackCandidate: ctx.fallback?.professionalId ?? null,
    sessionUpdates: ctx.sessionUpdates,
    scorecard: ctx.scorecard.map(({ professionalId, score, reasons, fullCoverage }) => ({ professionalId, score, reasons, fullCoverage }))
  }
};
return [{ json: {
  ok: true, project: 'ActiveFlow', scenario: 'continuity', status: 'awaiting_human_approval',
  requestId: ctx.requestId, correlationId: ctx.correlationId, idempotencyKey: ctx.idempotencyKey,
  message: 'A version-checked proposal was created. No session has changed yet.', proposal,
  audit: { correlationId: ctx.correlationId, idempotencyKey: ctx.idempotencyKey, timestamp: new Date().toISOString(), externalWrites: 0, companySystemsContacted: 0 },
  portfolioSafety: { syntheticData: true, proprietaryCode: false, companyEndpoints: false, credentials: false }
} }];
